"""High level tests to verify dynamics with a single TLS"""#%%import pytestimport QwaveMPS as qmpsimport numpy as npfrom ..benchmarks import *import itertoolsdef norm_sq(r):    return np.sinh(r)**2photon_num=[6]zetas = [[0,0.1],[0,0.2]]initial_pops = [0]gaussian_env = [True]initial_test_conditions = list(itertools.product(photon_num,zetas, initial_pops, gaussian_env))        @pytest.mark.parametrize("photon_num,zeta, initial_pop, gaussian_env", initial_test_conditions)def test_squeezed_pulse(photon_num,zeta, initial_pop, gaussian_env):    input_params = qmps.parameters.InputParams(        delta_t=0.1,         tmax = 10,        d_sys_total=np.array([2]),        d_t_total=np.array([photon_num+1,photon_num+1]),        gamma_l=0.5,        gamma_r = 0.5,          bond_max=min(2**3,2**(photon_num+1)),    )    tmax=input_params.tmax    delta_t=input_params.delta_t    tlist=np.arange(0,tmax+delta_t,delta_t)    sys_initial_state = np.zeros((1,2,1))    sys_initial_state[:,0,:] = np.sqrt(1 - initial_pop)    sys_initial_state[:,1,:] = np.sqrt(initial_pop)    if gaussian_env:        pulse_center = 3        sigma = 1        pulse_time = input_params.tmax        pulse_env = qmps.gaussian_envelope(pulse_time, input_params, sigma, pulse_center)    else:        pulse_time = 1        pulse_env = qmps.tophat_envelope(pulse_time, input_params)    wg_initial_state = qmps.states.squeezed_pulse([None, pulse_env],pulse_time,input_params,zeta)    Hm=qmps.hamiltonian_1tls(input_params)    bins = qmps.t_evol_mar(Hm,sys_initial_state,wg_initial_state,input_params, show_progress=False)    # Calculate the two level system population    photon_pop_ops = [qmps.b_pop_l(input_params), qmps.b_pop_r(input_params)]    photon_b_ops = [qmps.b_r(input_params)]        photon_fluxes = np.real(qmps.single_time_expectation(bins.output_field_states, photon_pop_ops))    tls_pop = np.real(qmps.single_time_expectation(bins.system_states, qmps.tls_pop()))    total_quanta = tls_pop + np.cumsum(np.sum(photon_fluxes, axis=0)) * delta_t    photon_b = np.real(qmps.single_time_expectation(bins.input_field_states, photon_b_ops))    chiral = False    pulse_env = np.append(pulse_env, np.zeros(len(tlist) - len(pulse_env)))    pulse_env = qmps.normalize_pulse_envelope_integral(input_params.delta_t, pulse_env)          assert check_close(total_quanta[-1], norm_sq(zeta[-1]))    assert check_close(photon_b,np.zeros(len(photon_b)))    input_flux = np.real(    qmps.single_time_expectation(        bins.input_field_states,        qmps.b_pop_r(input_params),    )    )        pulse_env_padded = np.append(        pulse_env,        np.zeros(len(tlist) - len(pulse_env)),    )        pulse_env_padded = qmps.normalize_pulse_envelope_integral(        input_params.delta_t,        pulse_env_padded,    )        expected_input_flux = np.sinh(zeta[-1])**2 * np.abs(pulse_env_padded) ** 2        assert check_close(input_flux[1:], expected_input_flux[:-1])# %%